import{_ as o,o as r,c as t,a2 as s}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Security posture","description":"","frontmatter":{},"headers":[],"relativePath":"policies/security-posture.md","filePath":"policies/security-posture.md","lastUpdated":1793718415000}'),n={name:"policies/security-posture.md"};function a(i,e,d,c,l,h){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="security-posture" tabindex="-1">Security posture <a class="header-anchor" href="#security-posture" aria-label="Permalink to &quot;Security posture&quot;">​</a></h1><p>The rules the shell keeps when it runs untrusted code next to the user&#39;s identity. Each rule has a scenario in <code>features/</code> or a check in <code>scripts/</code>; a rule with neither is a wish.</p><h2 id="mount-rules" tabindex="-1">Mount rules <a class="header-anchor" href="#mount-rules" aria-label="Permalink to &quot;Mount rules&quot;">​</a></h2><ol><li><strong><code>srcdoc</code>, never <code>src</code>.</strong> The applet document is the verified bytes with the shell prelude and CSP injected outside the signed content. A <code>src</code> URL would give the applet an origin and a network path the shell does not mediate.</li><li><strong><code>sandbox=&quot;allow-scripts&quot;</code> only.</strong> Never <code>allow-same-origin</code>, never <code>allow-top-navigation</code>, never <code>allow-popups</code>. The frame has an opaque origin and cannot reach the shell&#39;s storage or DOM.</li><li><strong>The guard&#39;s CSP, unchanged by profile.</strong> <code>createAppletCsp(profile)</code> is applied through <code>prepareNappletSrcdoc</code>; it returns the same policy for every profile. No grant, profile or setting alters it. See <a href="./../concepts/guard#why-csp-never-loosens">Guard</a>.</li><li><strong><code>denyNappletControllerAccess(frame)</code></strong> before the frame is attached, so the applet cannot reach a service worker or controller the shell registered.</li><li><strong>Order: register → set environment → observe frame → assign <code>srcdoc</code>.</strong> <code>originRegistry.register(contentWindow, windowId, identity)</code>, then <code>originRegistry.setEnvironment(contentWindow, environment)</code>, then <code>bridge.observeFrame(frame, windowId)</code>, then <code>frame.srcdoc = plan.srcdoc</code>. Assigning <code>srcdoc</code> first would let the document&#39;s first message arrive before the shell knows who it is.</li><li><strong>Remove the iframe on every revocation reason.</strong> <code>window-message</code>, <code>second-hello</code>, <code>invalid-hello</code>, <code>second-load</code>, <code>port-closed</code> and <code>host</code> all end with the frame gone and the guard&#39;s state for the window forgotten. A revoked window&#39;s identity is never re-bound to the same frame.</li></ol><h2 id="identity-rules" tabindex="-1">Identity rules <a class="header-anchor" href="#identity-rules" aria-label="Permalink to &quot;Identity rules&quot;">​</a></h2><ol start="7"><li><strong>Verified bytes come from <code>@kehto/nip/5d</code> <code>resolveNapplet</code>.</strong> Gateways and caches are accelerators; the hash is the identity. Cached bytes are re-verified on every read.</li><li><strong>Identity is <code>(dTag, artifactHash)</code> plus one port.</strong> Grants are keyed by that identity; a new build is a new identity with no grants.</li><li><strong>Restrictive by narrowing.</strong> <code>resolveEnvironment</code> returns only granted domains; kehto intersects, so the hook can only remove. The runtime&#39;s permissive default is never reached for an ungranted domain.</li></ol><h2 id="key-rules" tabindex="-1">Key rules <a class="header-anchor" href="#key-rules" aria-label="Permalink to &quot;Key rules&quot;">​</a></h2><ol start="10"><li><strong>Keys live only inside applesauce signer instances.</strong> <code>ExtensionSigner</code>, <code>NostrConnectSigner</code>, <code>PasswordAccount</code>&#39;s wrapped signer. kernl never holds raw key bytes and never serialises a private key outside <code>PasswordAccount</code>.</li><li><strong>Applets never see <code>window.nostr</code>.</strong> The sandbox has no extension injection, and the shell does not forward one.</li><li><strong>Every signature the applet asks for goes through consent or an existing grant</strong>, and destructive kinds (0, 3, 5, 10002) are shown as semantic diffs before signing.</li></ol><h2 id="network-rules" tabindex="-1">Network rules <a class="header-anchor" href="#network-rules" aria-label="Permalink to &quot;Network rules&quot;">​</a></h2><ol start="13"><li><strong>No applet network path exists outside the shell.</strong> All bytes arrive through the <code>resource</code> domain and a bridge. The HTTP bridge enforces <code>https</code> only, 3 redirects, 10 MiB, 20 s and a private-address block re-checked on every hop.</li><li><strong>One <code>RelayPool</code>.</strong> No service, provider or bridge opens its own connection. Adapters over the shared pool satisfy kehto&#39;s contracts.</li><li><strong>Hidden windows are deferred, not served.</strong> The visibility gate holds their traffic; the hidden resource allowance caps their requests.</li></ol><h2 id="log-rules" tabindex="-1">Log rules <a class="header-anchor" href="#log-rules" aria-label="Permalink to &quot;Log rules&quot;">​</a></h2><ol start="16"><li><strong>Secrets never appear in logs, guard events or consent summaries.</strong> <code>GuardEvent.reason</code> is a stable prefixed string; <code>NappletRevocation.detail</code> never includes message payloads; <code>describeChange</code> output names fields, not key material.</li><li><strong>Guard events are shown to the user</strong>, with the applet and the reason. They are not sent anywhere.</li></ol><h2 id="dependency-rules" tabindex="-1">Dependency rules <a class="header-anchor" href="#dependency-rules" aria-label="Permalink to &quot;Dependency rules&quot;">​</a></h2><ol start="18"><li><strong><code>nostr-tools</code> is never imported by kernl source.</strong> It is a transitive peer of kehto and applesauce only.</li><li><strong>Published packages have zero framework dependencies.</strong> <code>svelte</code>, <code>react</code>, <code>vue</code>, <code>preact</code>, <code>solid-js</code> and <code>lit</code> are forbidden in every <code>packages/*/package.json</code>.</li><li><strong>Leaf packages do not import <code>@kehto/*</code></strong>, except <code>@kernl/guard</code>, which imports <code>@kehto/firewall</code>. Only <code>@kernl/core</code> composes kehto.</li></ol><p>Rules 18 to 20 are enforced by <code>scripts/check-dependency-rules.mjs</code> (<code>pnpm check:deps</code>). Rules 1 to 17 are scenarios in <code>packages/*/features/</code> and <code>features/</code>, and the mount rules are additionally exercised in the browser by the Playwright suite.</p><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>A posture violation is a bug of the highest severity in this repository, above any feature. Report it as an issue on <code>kernlize/web</code> with the rule number. If it involves a kehto seam, the issue is filed upstream too, and <code>DECISIONS.md</code> records the gap.</p>',17)])])}const g=o(n,[["render",a]]);export{p as __pageData,g as default};
